import {labObjects,vesselInstructions} from './lab-data.js';
import {ObjectLabScene} from './lab-scene.js';
import {createVesselState,advanceVessel,vesselStep,RhythmRecorder,MAX_RECORDING_SECONDS} from './lab-state.js';
import {LabDrumAudio} from './lab-audio.js';
const query=new URLSearchParams(location.search),id=labObjects[query.get('object')]?query.get('object'):'drum',config=labObjects[id],isDrum=id==='drum';
const root=document.getElementById('lab-root');document.title=config.name+' · 器物实验室';document.body.dataset.object=id;document.querySelectorAll('[data-lab]').forEach(a=>{if(a.dataset.lab===id)a.setAttribute('aria-current','page')});
const buttons=(items,attr)=>items.map(([v,t])=>`<button ${attr}="${v}">${t}</button>`).join('');
root.innerHTML=`<div class="lab-layout"><section class="lab-viewport" aria-label="三维器物互动"><div class="lab-stage"></div><div class="lab-title"><span class="lab-kicker">${config.english}</span><h1>${config.title}</h1><p>${config.intro}</p></div><div class="lab-camera" aria-label="观察角度">${buttons([['home','全貌 ⤢'],['front','正面'],['top','俯视']],'data-camera')}</div><div class="model-label" data-part-label hidden></div>${isDrum?'':`<button class="model-label lift-handle" data-lift-handle aria-label="向上拖动提起铜尊">↕ 提起铜尊</button>`}<div class="lab-scene-note"><span>${isDrum?'TOUCH THE DRUM / 点击鼓面':'LIFT · PLACE · POUR / 提 · 放 · 斟'}</span>${isDrum?'空处拖动旋转 · 滚轮缩放':'拖动内尊升降 · 空处拖动旋转'}</div>${isDrum?'<div class="lab-surface-control"><button class="surface-toggle" aria-pressed="true" data-skin>鼓面示意 ✓</button></div>':''}<div class="lab-loader" role="status"><b>正在展开器物</b><span>载入三维模型</span><progress max="1" value="0"></progress></div></section><aside class="lab-side"><div class="lab-panel-label">${isDrum?'用手，写一段声音':'用手，读懂两件器物'}</div>${isDrum?drumPanel():vesselPanel()}<section class="knowledge"><div class="lab-panel-label">操作之后，发现什么</div><div class="part-tabs">${buttons(isDrum?[['tiger','虎座'],['phoenix','凤架'],['drum','悬鼓']]:[['zun','内尊'],['pan','外盘'],['cool','合用']],'data-fact')}</div><h3 class="fact-title"></h3><p class="fact-copy"></p></section><a class="lab-object-link" href="object.html?id=${id}">查看器物档案与照片 ↗</a><details class="lab-sources"><summary>资料与示意说明</summary><p>${config.note}</p><a href="${config.source}" target="_blank" rel="noopener">湖北省博物馆 · ${isDrum?'器物记录':'藏品用途说明'} ↗</a>${config.catalog?`<br><a href="${config.catalog}" target="_blank" rel="noopener">馆方器物档案 ↗</a>`:''}</details></aside></div>`;
function drumPanel(){return `<h2 class="side-heading">先敲中央，再试试边缘。</h2><p>敲的位置不同，音色与波纹也会变化。想留下一段，就先开始录制。</p><div class="drum-hit-buttons">${buttons([['center','中央<small>A · 低沉</small>'],['middle','轻敲<small>S · 柔和</small>'],['edge','边缘<small>D · 明亮</small>']],'data-strike')}</div><button class="lab-primary" data-record>录一段自己的节奏 <span>●</span></button><div class="lab-actions"><button data-play disabled>回放节奏 ▶</button><button data-clear disabled>重新开始 ↺</button></div><div class="rhythm-strip" aria-label="已记录的鼓点"><span class="empty-rhythm">你的鼓点，会留在这里。</span></div><p class="record-status" role="status">最多录制 16 秒，不使用麦克风。</p><label class="lab-panel-label">音量 <input data-volume type="range" min="0" max="100" value="65" aria-label="鼓声音量"></label><p class="touch-hint">声音为合成示意。也可以按 A / S / D 敲击。</p>`}
function vesselPanel(){return `<div class="lab-steps" aria-label="探索进度">${Array.from({length:5},(_,i)=>`<i class="lab-step" data-step="${i}"></i>`).join('')}</div><div class="vessel-task"><span class="task-number">01</span><h2></h2><p></p></div><button class="lab-primary" data-vessel-action>提起铜尊 <span>↑</span></button><div class="lift-slider"><label for="lift-amount"><span>铜尊位置</span><output>合拢</output></label><input id="lift-amount" type="range" min="0" max="100" value="0" aria-label="铜尊提起高度"></div><div class="ice-counter"><span>外盘的冰</span>${Array.from({length:6},(_,i)=>`<i data-ice="${i}"></i>`).join('')}</div><div class="wine-meter" aria-label="内尊酒液"><i></i></div><p class="vessel-feedback" role="status">先试着把中央的尊向上提起。</p><button class="small-action cutaway-toggle" data-cutaway aria-pressed="false">看内外两层 ◉</button><div class="cool-meter" hidden><div class="labels"><span>常温</span><span>渐凉</span></div><div class="track"><i class="marker"></i></div></div><div class="lab-actions"><button data-vessel-reset>重新探索 ↺</button></div><p class="touch-hint">拖动与按钮都可以操作。内腔、酒液和冷却为教学示意。</p>`}
let scene,vessel=createVesselState(),lastStep=-1,pouring=false,disposed=false,recordStarted=0,skinVisible=true,lastUI=0,interactionGeneration=0,playbackRequested=false;
const recorder=new RhythmRecorder(),audio=new LabDrumAudio({volume:.65}),abort=new AbortController(),signal=abort.signal;
function fact(name){const f=config.facts[name];if(!f)return;root.querySelector('.fact-title').textContent=f.title;root.querySelector('.fact-copy').textContent=f.body;root.querySelector('.lab-title p').textContent=f.title+' · '+f.body;root.querySelectorAll('[data-fact]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.fact===name));if(name!=='cool')scene?.highlight(name);if(name==='cool'&&!isDrum&&vesselStep(vessel)===4)setCutaway(true)}
function rhythmUI(){const events=recorder.events;root.querySelector('.rhythm-strip').innerHTML=events.length?events.map((e,i)=>`<i class="rhythm-dot" data-beat="${i}" data-edge="${e.radius>.6}" style="height:${10+e.strength*24}px" title="第 ${i+1} 次敲击"></i>`).join(''):'<span class="empty-rhythm">你的鼓点，会留在这里。</span>';root.querySelector('[data-play]').disabled=!events.length||recorder.recording;root.querySelector('[data-clear]').disabled=!events.length&&!recorder.recording;root.querySelector('[data-record]').classList.toggle('recording',recorder.recording);root.querySelector('[data-record]').innerHTML=recorder.recording?'结束录制 <span>■</span>':'录一段自己的节奏 <span>●</span>';root.querySelector('[data-record]').setAttribute('aria-pressed',String(recorder.recording))}
function playbackUI(active){playbackRequested=active;if(!isDrum)return;const button=root.querySelector('[data-play]');button.textContent=active?'停止回放 ■':'回放节奏 ▶';button.setAttribute('aria-pressed',String(active));if(!active)root.querySelectorAll('[data-beat]').forEach(x=>x.classList.remove('active'))}
function stopAudioTransport(){interactionGeneration++;audio.stop();playbackUI(false)}
function stopRecording(){stopAudioTransport();recorder.stop(performance.now());rhythmUI();const e=recorder.events;root.querySelector('.record-status').textContent=e.length?`留下了 ${e.length} 次敲击。回放时，再看一次鼓面的振动。`:'还没有敲下鼓点，可以再录一次。'}
async function strike(radius,strength,point){
 if(!scene?.ready||!skinVisible)return;
 scene.pulse(radius,strength,point);recorder.hit(radius,strength,performance.now());rhythmUI();fact('drum');
 if(!recorder.recording)root.querySelector('.record-status').textContent=radius>.6?'这一下靠近边缘：听到更明亮的合成音色了吗？':'这一下靠近中央：鼓面的波纹由敲击处展开。';
 const generation=interactionGeneration;try{await audio.start();if(!disposed&&!document.hidden&&generation===interactionGeneration)audio.strike(radius,strength)}catch{if(!disposed&&generation===interactionGeneration)root.querySelector('.record-status').textContent='声音未能启动，请再点击一次。'}
}
function vesselAction(action,angle){const before=vessel;vessel=advanceVessel(vessel,action);if(angle!==undefined&&scene)scene.pendingIceAngle=angle;scene?.setVessel(vessel);if(action.type==='lift'&&vessel.lift>.08)stopPouring();vesselUI();if(action.type==='ice'&&vessel.ice>before.ice){root.querySelector('.vessel-feedback').textContent=`第 ${vessel.ice} 块冰留在外盘。${vessel.ice>=3?'现在把尊放回去。':'再添一些。'}`;fact('pan')}return vessel}
function vesselUI(){const step=vesselStep(vessel);root.querySelectorAll('[data-step]').forEach(el=>{el.classList.toggle('done',+el.dataset.step<step);el.classList.toggle('current',+el.dataset.step===step)});const [title,hint]=vesselInstructions[step];root.querySelector('.task-number').textContent=String(step+1).padStart(2,'0');root.querySelector('.vessel-task h2').textContent=title;root.querySelector('.vessel-task>p').textContent=hint;const main=root.querySelector('[data-vessel-action]');main.textContent=['提起铜尊 ↑','给外盘添一块冰 ＋','放回铜尊 ↓','按住斟酒 ↓','再看一眼内外两层 ◉'][step];main.disabled=!scene?.ready;main.dataset.action=['lift','ice','return','wine','inspect'][step];root.querySelector('#lift-amount').value=Math.round(vessel.lift*100);root.querySelector('.lift-slider output').textContent=vessel.lift<.08?'合拢':Math.round(vessel.lift*100)+'%';root.querySelectorAll('[data-ice]').forEach(el=>el.classList.toggle('filled',+el.dataset.ice<vessel.ice));root.querySelector('.wine-meter i').style.width=vessel.wine*100+'%';root.querySelector('.wine-meter').setAttribute('aria-label',`内尊酒液 ${Math.round(vessel.wine*100)}%`);root.querySelector('.cool-meter').hidden=step!==4;root.querySelector('.cool-meter .marker').style.left=vessel.cooling*99+'%';
 if(step!==lastStep){lastStep=step;root.querySelector('.vessel-feedback').textContent=['尊和盘是两件器物，先让它们分开。','外盘露出来了。冰可以留在这一层。','冰已放好，把内尊安放回中央。','酒斟入内尊，与外盘的冰隔开。','冰在外，酒在内。两件器物一起完成冰镇。'][step];fact(step<2?'zun':step<3?'pan':'cool');}
}
function setCutaway(v){scene?.setCutaway(v);const b=root.querySelector('[data-cutaway]');b.setAttribute('aria-pressed',String(v));b.textContent=v?'恢复器表 ◉':'看内外两层 ◉'}
function startPouring(){if(!scene?.ready||vesselStep(vessel)!==3)return;pouring=true;scene.setPouring(true)}
function stopPouring(){pouring=false;scene?.setPouring(false)}
function pause(){stopPouring();if(isDrum&&recorder.recording)stopRecording();else stopAudioTransport()}
function bindDrum(){
 root.querySelector('[data-record]').onclick=()=>{if(recorder.recording){stopRecording();return}stopAudioTransport();recorder.start(performance.now());recordStarted=performance.now();rhythmUI();root.querySelector('.record-status').textContent='录制中，点鼓面留下你的节奏。'};
 root.querySelectorAll('[data-strike]').forEach(b=>b.onclick=()=>{const spec={center:[.08,.9],middle:[.35,.38],edge:[.82,.7]}[b.dataset.strike];strike(...spec)});
 root.querySelector('[data-play]').onclick=async()=>{
  if(playbackRequested||audio.playing){stopAudioTransport();return}
  stopAudioTransport();const generation=interactionGeneration;playbackUI(true);
  try{const started=await audio.play(recorder.events,{onHit:(e,i)=>{if(generation!==interactionGeneration||disposed)return;scene.pulse(e.radius,e.strength);root.querySelectorAll('[data-beat]').forEach(x=>x.classList.toggle('active',+x.dataset.beat===i))},onEnd:()=>{if(generation===interactionGeneration&&!disposed)stopAudioTransport()}});if(!started&&generation===interactionGeneration)stopAudioTransport()}
  catch{if(generation!==interactionGeneration||disposed)return;stopAudioTransport();root.querySelector('.record-status').textContent='声音暂时未能启动，请再次点击。'}
 };
 root.querySelector('[data-clear]').onclick=()=>{stopAudioTransport();recorder.start(performance.now());recorder.stop(performance.now());rhythmUI();root.querySelector('.record-status').textContent='空白一段，等你重新开始。'};
 root.querySelector('[data-volume]').oninput=e=>audio.setVolume(+e.target.value/100);
 root.querySelector('[data-skin]').onclick=e=>{skinVisible=!skinVisible;scene.setSkin(skinVisible);e.currentTarget.setAttribute('aria-pressed',String(skinVisible));e.currentTarget.textContent=skinVisible?'鼓面示意 ✓':'显示鼓面示意';if(!skinVisible)pause()};
 document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;const map={a:[.08,.9],s:[.35,.38],d:[.82,.7]};if(map[e.key.toLowerCase()]){e.preventDefault();strike(...map[e.key.toLowerCase()])}},{signal});
 rhythmUI();playbackUI(false);
}
function bindVessel(){
 root.querySelector('#lift-amount').oninput=e=>vesselAction({type:'lift',value:+e.target.value/100});
 const main=root.querySelector('[data-vessel-action]');let pourDown=0,ignorePourClick=false;main.addEventListener('pointerdown',e=>{if(main.dataset.action==='wine'){pourDown=performance.now();main.setPointerCapture(e.pointerId);startPouring()}},{signal});
 const end=e=>{if(pourDown){ignorePourClick=performance.now()-pourDown>180;pourDown=0}stopPouring();if(e.pointerId!==undefined&&main.hasPointerCapture(e.pointerId))main.releasePointerCapture(e.pointerId)};main.addEventListener('pointerup',end,{signal});main.addEventListener('pointercancel',end,{signal});main.addEventListener('lostpointercapture',stopPouring,{signal});
 main.onclick=e=>{if(ignorePourClick){ignorePourClick=false;return}const step=vesselStep(vessel);if(step===0)vesselAction({type:'lift',value:1});else if(step===1)vesselAction({type:'ice'});else if(step===2)vesselAction({type:'lift',value:0});else if(step===3&&!pouring){vesselAction({type:'wine',value:vessel.wine+.22})}else if(step===4)setCutaway(!scene.cutaway)};
 main.addEventListener('keydown',e=>{if([' ','Enter'].includes(e.key)&&main.dataset.action==='wine'){e.preventDefault();startPouring()}},{signal});main.addEventListener('keyup',e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();stopPouring()}},{signal});main.addEventListener('blur',stopPouring,{signal});
 root.querySelector('[data-cutaway]').onclick=()=>setCutaway(!scene.cutaway);
 root.querySelector('[data-vessel-reset]').onclick=()=>{stopPouring();vesselAction({type:'reset'});setCutaway(false);scene.view('home')};
 const handle=root.querySelector('[data-lift-handle]');let drag=null;
 handle.addEventListener('pointerdown',e=>{if(e.button!==0)return;if(drag){drag.moved=true;return}if(e.isPrimary===false)return;drag={pointerId:e.pointerId,x:e.clientX,y:e.clientY,value:vessel.lift,moved:false};handle.setPointerCapture(e.pointerId);e.preventDefault()},{signal});
 handle.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pointerId)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>=4)drag.moved=true;vesselAction({type:'lift',value:Math.max(0,Math.min(1,drag.value+(drag.y-e.clientY)/160))})},{signal});
 const cancelDrag=e=>{if(!drag||(e?.pointerId!==undefined&&e.pointerId!==drag.pointerId))return;const pointerId=drag.pointerId;drag=null;if(handle.hasPointerCapture(pointerId))handle.releasePointerCapture(pointerId)};
 const finish=e=>{if(!drag||e.pointerId!==drag.pointerId)return;const click=!drag.moved&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<4;cancelDrag(e);if(click)vesselAction({type:'lift',value:vessel.lift>.5?0:1})};
 handle.addEventListener('pointerup',finish,{signal});handle.addEventListener('pointercancel',cancelDrag,{signal});handle.addEventListener('lostpointercapture',cancelDrag,{signal});handle.addEventListener('blur',cancelDrag,{signal});window.addEventListener('blur',cancelDrag,{signal});handle.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','Enter',' '].includes(e.key)){e.preventDefault();vesselAction({type:'lift',value:['Enter',' '].includes(e.key)?vessel.lift>.5?0:1:vessel.lift+(e.key==='ArrowUp'?.1:-.1)})}},{signal});
 vesselUI();
}
try{
 scene=new ObjectLabScene(root.querySelector('.lab-stage'),config,{
  onProgress:value=>{const loader=root.querySelector('.lab-loader');if(value===null)loader.querySelector('progress').removeAttribute('value');else{loader.querySelector('progress').value=value;loader.querySelector('span').textContent='三维模型 · '+Math.round(value*100)+'%'}},
  onReady:()=>{root.querySelector('.lab-loader').hidden=true;document.body.dataset.ready='true';if(!isDrum)vesselUI()},
  onStrike:strike,onLift:v=>vesselAction({type:'lift',value:v}),onIce:angle=>vesselAction({type:'ice'},angle),onPart:fact,onPause:pause,
  onFrame:(dt,now)=>{
   if(!scene?.ready)return;
   if(isDrum){if(recorder.recording){const seconds=(now-recordStarted)/1000;if(seconds>=MAX_RECORDING_SECONDS)stopRecording();else if(now-lastUI>120){root.querySelector('.record-status').textContent=`录制中 ${seconds.toFixed(1)} / 16 秒 · ${recorder.events.length} 次敲击`;lastUI=now}}}
   else{if(pouring){vesselAction({type:'wine',value:Math.min(1,vessel.wine+dt*.43)});if(vessel.wine>=1)stopPouring()}if(vesselStep(vessel)===4&&vessel.cooling<1){vessel=advanceVessel(vessel,{type:'tick',dt});scene.setVessel(vessel);if(now-lastUI>100){vesselUI();lastUI=now}}
    const h=root.querySelector('[data-lift-handle]'),pos=scene.screenPoint(scene.anchor('zun'));h.style.left=Math.max(60,Math.min(scene.width-60,pos.x))+'px';h.style.top=Math.max(105,Math.min(scene.host.parentElement.clientHeight-80,pos.y-33))+'px';h.hidden=!pos.visible;h.textContent=vessel.lift>.5?'↕ 放回铜尊':'↕ 提起铜尊';
   }
   const label=root.querySelector('[data-part-label]');const part=scene.activePart,valid=part&&config.facts[part];label.hidden=!valid;if(valid){const p=scene.screenPoint(scene.anchor(part));label.hidden=!p.visible;label.style.left=Math.max(50,Math.min(scene.width-50,p.x))+'px';label.style.top=Math.max(115,Math.min(scene.host.parentElement.clientHeight-60,p.y-35))+'px';label.textContent=isDrum?({tiger:'卧虎承托',phoenix:'凤鸟举鼓',drum:'悬挂与承托'})[part]:part==='zun'?'内尊 · 盛酒':'外盘 · 盛冰';if(!isDrum&&part==='zun')label.hidden=true}
  }
 });
 root.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>scene.view(b.dataset.camera));root.querySelectorAll('[data-fact]').forEach(b=>b.onclick=()=>fact(b.dataset.fact));isDrum?bindDrum():bindVessel();fact(isDrum?'tiger':'zun');await scene.load();
}catch(e){console.error(e);root.querySelector('.lab-loader').hidden=true;root.querySelector('.lab-viewport').insertAdjacentHTML('beforeend','<div class="lab-error">模型暂时未能打开，请刷新重试。<a href="object.html?id='+id+'">先查看器物档案 ↗</a></div>');document.body.dataset.error='true'}
window.addEventListener('pagehide',e=>{pause();if(e.persisted){scene?.suspend();return}disposed=true;audio.dispose();scene?.dispose();abort.abort()});
window.addEventListener('pageshow',e=>{if(e.persisted&&!disposed)scene?.resume()});
